public class Main {
    static int[] corpFlightBookings(int[][] bookings, int n) {
        int[] diff = new int[n + 1];
        for (int[] b : bookings) {
            diff[b[0] - 1] += b[2];              // booking begins here (0-indexed)
            diff[b[1]] -= b[2];                   // and ends right after 'last'
        }
        int[] result = new int[n];
        int running = 0;
        for (int i = 0; i < n; i++) {
            running += diff[i];                    // one sweep reconstructs every flight's total
            result[i] = running;
        }
        return result;
    }
}

